from itertools import product
from collections import Counter


def ledger(data, priority, tax_base, refunds, half_up):
    def rounded(n, d):
        return (n + d // 2) // d if half_up else n // d

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((event.get("revision", 0), pos) if priority == "revision_first"
               else (event.get("sequence", 0), event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode_half_up = data["rounding"] == "half_up"
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000) if mode_half_up else raw * (10000 - discount) // 10000
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0), 10000) if mode_half_up else base * event.get("tax_bp", 0) // 10000
        amount = net + tax
        if refunds and event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def resolve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    options = []
    for name in names:
        blocked = data.get("blocked", {}).get(name, [])
        pin = data.get("pins", {}).get(name)
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked and (pin is None or row["version"] == pin)]
        options.append([None] + versions)

    best_vector = None
    best = None
    for values in product(*options):
        installed = dict(zip(names, values))
        constraints = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        graph = {}
        reached = set()
        stack = list(data["roots"])
        valid = True
        while stack and valid:
            name = stack.pop()
            if name in reached:
                continue
            version = installed[name]
            if version is None:
                valid = False
                break
            row = next(r for r in packages[name] if r["version"] == version)
            reached.add(name)
            graph[name] = []
            for low, high in constraints[name]:
                if not low <= version <= high:
                    valid = False
                    break
            if not valid:
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                graph[name].append(other)
                constraints.setdefault(other, []).append((dep["min"], dep["max"]))
                stack.append(other)

        if not valid or any(installed[n] is not None for n in names if n not in reached):
            continue
        if any(not (lo <= installed[n] <= hi) for n, ranges in constraints.items()
               for lo, hi in ranges):
            continue

        color = {}
        def visit(name):
            if color.get(name) == 1:
                return False
            if color.get(name) == 2:
                return True
            color[name] = 1
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            color[name] = 2
            return True
        if not all(visit(name) for name in reached):
            continue

        vector = tuple(installed[n] if installed[n] is not None else -1 for n in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {n: installed[n] for n in names if installed[n] is not None}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def schedule(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        selected = [jobs[i] for i in range(n) if mask >> i & 1]
        if len(selected) != k:
            continue
        ids = {job["id"] for job in selected}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in selected:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, change in sorted(events, key=lambda x: (x[0], x[1])):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in selected)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def routes(data):
    import heapq
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                choices.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in choices:
                when = depart + duration
                if when > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if when < dist.get(next_state, float("inf")):
                    dist[next_state] = when
                    heapq.heappush(queue, (when, next_node, next_mask, left))
    return {"arrival": None}


