    "component_01": lambda d: ledger(d, "revision_first", "original", False, False),
    "component_02": lambda d: ledger(d, "sequence_first", "original", True, False),
    "component_03": lambda d: ledger(d, "revision_first", "discounted", True, False),
    "component_04": lambda d: ledger(d, "sequence_first", "discounted", True, False),
    "component_05": lambda d: ledger(d, "revision_first", "original", False, True),
    "component_06": resolve,
    "component_07": schedule,
    "component_08": routes,
}

